import json, re, sys, os
nbpath="/workdir/executed_RQ1.ipynb"
if not os.path.exists(nbpath):
    print("EXECUTED_NOTEBOOK_NOT_FOUND")
    sys.exit(0)
nb=json.load(open(nbpath))
names=["Test","Build","Release","Analyze","Lint","Linux","Update","Integration","Deploy","Sync"]
pat=re.compile(r"^\\s*(" + "|".join(names) + r")\\b.*$", re.M)
found=[]
for cell in nb.get("cells",[]):
    # search cell source too
    src = "".join(cell.get("source","") or "")
    for m in pat.finditer(src):
        lines = src.splitlines()
        idx = lines.index(m.group(0))
        seg = "\\n".join(lines[max(0, idx-3): idx+3])
        found.append(seg)
    for out in cell.get("outputs",[]):
        texts=[]
        if out.get("output_type")=="stream":
            texts.append("".join(out.get("text","") or ""))
        elif out.get("output_type") in ("execute_result","display_data"):
            data=out.get("data",{})
            for key in ("text/markdown","text/plain","text/html"):
                if key in data:
                    v=data[key]
                    texts.append(v if isinstance(v,str) else "".join(v))
        for txt in texts:
            if not txt:
                continue
            for m in pat.finditer(txt):
                lines = txt.splitlines()
                # find the first occurrence index for this match line
                for i,l in enumerate(lines):
                    if pat.match(l):
                        start=max(0,i-3)
                        end=min(len(lines), i+3)
                        seg="\\n".join(lines[start:end])
                        found.append(seg)
                        break
# Deduplicate and print
if not found:
    print("NO_TABLE_ROWS_FOUND")
else:
    seen=set()
    out=[]
    for seg in found:
        if seg in seen:
            continue
        seen.add(seg)
        out.append(seg)
    print("\\n\\n---\\n\\n".join(out))
PY' 
